"""controller: a schedule firing for an application that has left the configuration.

The controller logs it, ignores the event and keeps running. The set-up is
controller_platform's, up to interactive mode.
"""

from scenarios import controller_platform as base

DAEMON = "controller"
DEVICES = []
sandbox_setup = base.sandbox_setup


def normalise_record(record):
    # The schedule's id, generated by the controller, shows in the signal.
    return [base.UUID.sub("<uuid>", line) for line in base.normalise_record(record)]


def trigger(platform, p, fake, step):
    import re
    from pathlib import Path
    platform.send(p, 'id: "p-sched" scheduleConfig { scheduleApp { apiKey: "app-new" instance: "inst1" '
                     'schedule { schedulePeriodic { period: 600 } } } }')
    step("a periodic schedule for app-new", 'correlationId: "p-sched"', "add_periodic_entry")
    entries = re.findall(r'add_periodic_entry\("([^"]+)"', Path(fake.log).read_text())
    platform.send(p, 'id: "p-config2" config { configapp { apiKey: "app-same" version: "2" name: "Same" '
                     'deployment: "hosted" configInstance { name: "inst2" uuid: "cfg-2" } } lang: "fr-FR" }')
    step("app-new leaves the configuration", "karotzinfo_response", settle=3.0)
    if entries:
        fake.emit("Scheduler", "schedule_event", "si", entries[-1], 1)
    step("its schedule fires", settle=3.0, timeout=20)


def drive(d, bus):
    return base.drive(d, bus, trigger=trigger, when="interactive")
